#!/usr/bin/env python3
"""Rust-first workspace attachment through actual CLI project initialization."""
import hashlib
import json
import os
from pathlib import Path
import subprocess
import shlex
import shutil
import sys
import tempfile
import tomllib

repo = Path(__file__).resolve().parents[3]
binary = Path(os.environ.get('FORKLAUNCH_CLI', repo / 'cli/target/debug/forklaunch')).resolve()
output = repo / 'cli/tests/output/rust-typescript-attach'
output.mkdir(parents=True, exist_ok=True)
root = Path(tempfile.mkdtemp(prefix='run.', dir=output)).resolve()
app = root / 'app'
account = 'parity-offline-' + root.name.removeprefix('run.').replace('_', '-')
account_path = Path.home() / '.forklaunch/accounts' / f'{account}.toml'
assert not account_path.exists()
env = {**os.environ, 'FORKLAUNCH_ACCOUNT': account, 'FORKLAUNCH_SKIP_FORMAT': '1', 'CARGO_INCREMENTAL': '0',
       'RUSTUP_TOOLCHAIN': 'stable'}
env.setdefault('CARGO_TARGET_DIR', str(repo / 'cli/target'))
if not env.get('FORKLAUNCH_WORKER_RUNTIME_LOCKED'):
    shutil.rmtree(root)
    sys.exit(subprocess.run([sys.executable, str(repo / 'cli/tests/fixtures/worker_runtime_lock.py'),
        '-c', shlex.join([sys.executable, str(Path(__file__).resolve())])], env=env).returncode)


print(f'CLI SHA256: {hashlib.file_digest(binary.open("rb"), "sha256").hexdigest()}', flush=True)

def run(*args, success=True):
    result = subprocess.run([str(binary), *args, '--path', str(app)], cwd=root, env=env,
        capture_output=True, text=True, timeout=300)
    print(result.stdout, end='', flush=True)
    if success:
        assert result.returncode == 0, result.stderr
    else:
        assert result.returncode != 0, result.stdout
    return result


def snapshot():
    return {str(path.relative_to(app)): ('link:' + os.readlink(path) if path.is_symlink()
        else hashlib.sha256(path.read_bytes()).hexdigest()) for path in app.rglob('*')
        if path.is_symlink() or path.is_file()}


def image_inventory():
    """Generated images, read from the stamped Dockerfiles and Compose."""
    services = json.loads(subprocess.check_output(['docker', 'compose', '-f', str(app / 'docker-compose.yaml'),
        'config', '--no-interpolate', '--format', 'json'], cwd=app, env=env, text=True))['services']
    images = {}
    for language in ['rust', 'typescript']:
        dockerfile = app / f'Dockerfile.{language}'
        if not dockerfile.is_file():
            continue
        assert dockerfile.read_text().startswith('# Generated by ForkLaunch (sha256:'), dockerfile
        # The builder service tags the image every process of that language shares.
        built = {service.get('image') for service in services.values()
                 if Path((service.get('build') or {}).get('dockerfile', '')).name == dockerfile.name}
        images[language] = {'processes': sorted(name for name, service in services.items()
                                                if service.get('image') in built)}
    lines = (app / 'Dockerfile.rust').read_text().splitlines()
    release = 'COPY --from=builder /app/target/release/'
    images['rust']['inputs'] = [json.loads(line[len('COPY '):])[0] for line in lines if line.startswith('COPY [')]
    images['rust']['binaries'] = [line[len(release):].split(' ')[0] for line in lines if line.startswith(release)]
    return images


def initialize(description):
    run('init', 'application', 'rust-first', '--modules-path', 'modules',
        '--database', 'postgresql', '--validator', 'zod', '--formatter', 'prettier', '--linter', 'oxlint',
        '--http-framework', 'express', '--runtime', 'node', '--test-framework', 'vitest',
        '-D', description, '-A', 'ForkLaunch', '-L', 'MIT')


try:
    initialize('Rust-first attachment')
    run('init', 'service', 'native-api', '--language', 'rust', '-D', 'Native API')
    run('init', 'library', 'native-models', '--language', 'rust', '-D', 'Native models')
    source = app / 'modules/native-api/lib.rs'
    source.write_text(source.read_text() + '\npub const APPLICATION_OWNED: bool = true;\n')
    original_source = source.read_bytes()
    original_cargo = tomllib.loads((app / 'Cargo.toml').read_text())
    original_image = image_inventory()['rust']
    package = json.loads((app / 'package.json').read_text())
    package['scripts']['user:owned'] = 'echo preserved'
    (app / 'package.json').write_text(json.dumps(package))
    before = snapshot()
    run('init', 'service', 'legacy-api', '--language', 'typescript', '-d', 'postgresql', '-D', 'Legacy API', '--dryrun')
    assert snapshot() == before, 'Dry run changed the application'
    failed = run('init', 'service', 'rust-first', '--language', 'typescript', '-d', 'postgresql', '-D', 'Invalid', success=False)
    assert snapshot() == before, 'Failed project initialization changed the application'
    run('init', 'service', 'legacy-api', '--language', 'typescript', '-d', 'postgresql', '-D', 'Legacy API')
    manifest = tomllib.loads((app / '.forklaunch/manifest.toml').read_text())
    assert manifest['language'] == manifest['applicationLanguage'] == 'mixed'
    assert manifest['runtime'] == 'node' and manifest['modules_path'] == 'modules'
    assert manifest['sdkTargets'] == ['typescript', 'rust']
    assert manifest['cargoWorkspace'] == 'Cargo.toml'
    assert {p['name'] for p in manifest['projects']} >= {'native-api', 'native-models', 'core', 'monitoring', 'client-sdk', 'legacy-api'}
    assert source.read_bytes() == original_source
    attached_cargo = tomllib.loads((app / 'Cargo.toml').read_text())
    assert set(attached_cargo['workspace']['members']) == set(original_cargo['workspace']['members']) | {'modules/legacy-api/sdk/rust'}
    attached_cargo['workspace']['members'] = original_cargo['workspace']['members']
    assert attached_cargo == original_cargo
    assert (app / 'Dockerfile.typescript').is_file()
    attached_image = image_inventory()['rust']
    assert attached_image['binaries'] == original_image['binaries']
    assert attached_image['processes'] == original_image['processes']
    assert set(attached_image['inputs']) == set(original_image['inputs']) | {'modules/legacy-api/sdk/rust/'}
    assert 'COPY modules/legacy-api/ modules/legacy-api/' not in (app / 'Dockerfile.rust').read_text()
    scripts = json.loads((app / 'package.json').read_text())['scripts']
    assert scripts['user:owned'] == 'echo preserved'
    assert 'cargo clippy' in scripts['rust:lint']
    assert json.loads((app / 'modules/package.json').read_text())['scripts']['lint']
    assert scripts['build'] == 'cargo build --workspace && pnpm -r --if-present run build'
    assert 'modules/*/sdk/typescript' in (app / 'pnpm-workspace.yaml').read_text()
    assert 'modules/*' in (app / 'pnpm-workspace.yaml').read_text()
    for path in (app / 'modules/legacy-api').rglob('*.ts'):
        assert b'/template/' not in path.read_bytes(), path
    run('init', 'library', 'legacy-models', '--language', 'typescript', '-D', 'Legacy models')
    run('init', 'worker', 'legacy-jobs', '--language', 'typescript', '-t', 'redis', '-d', 'postgresql', '-D', 'Legacy jobs')
    run('init', 'module', 'legacy-cac', '--language', 'typescript', '-m', 'cac-base', '-d', 'postgresql')
    compose = json.loads(subprocess.check_output(['docker', 'compose', '-f', str(app / 'docker-compose.yaml'),
        'config', '--no-interpolate', '--format', 'json'], cwd=app, env=env, text=True))
    assert compose['services']['native-api']['command'] == ['/app/bin/native-api']
    assert compose['services']['native-api']['image'] == 'rust-first-rust:local'
    images = image_inventory()
    assert set(images['rust']['processes']) == {'native-api'}
    assert all((app / name).is_file() for name in ['Dockerfile.rust', 'Dockerfile.typescript'])
    assert not (app / 'modules/Dockerfile').exists()
    for language in ['rust', 'typescript']:
        processes = images[language]['processes']
        assert len({compose['services'][name]['image'] for name in processes}) == 1
        builds = [compose['services'][name]['build'] for name in processes if 'build' in compose['services'][name]]
        assert builds and all(item['context'] == str(app) and Path(item['dockerfile']).as_posix().removeprefix('./') == 'Dockerfile.' + language for item in builds)
    listed = json.loads(subprocess.check_output(['pnpm', '-r', 'list', '--depth', '-1', '--json'], cwd=app, env=env, text=True))
    assert {'@rust-first/native-api', '@rust-first/legacy-api', '@rust-first/legacy-models'} <= {p.get('name') for p in listed}
    subprocess.run(['pnpm', 'install', '--ignore-scripts', '--no-frozen-lockfile'], cwd=app, env=env, check=True, timeout=300)
    subprocess.run(['pnpm', 'build'], cwd=app, env=env, check=True, timeout=1800)
    subprocess.run(['node', str(repo / 'cli/tests/fixtures/rust_typescript_service_startup.mjs'), str(app)],
        cwd=app, env=env, check=True, timeout=60)
    metadata = json.loads(subprocess.check_output(['cargo', 'metadata', '--no-deps', '--format-version', '1'], cwd=app, env=env))
    subprocess.run(['node', str(repo / 'cli/tests/fixtures/rust_mcp_service_startup.mjs'),
        str(Path(metadata['target_directory']) / 'debug/native-api')], cwd=app, env=env, check=True, timeout=120)
    print('PASS Rust-first TypeScript workspace attachment, dry run/failure preservation, project kinds, Cargo and HTTP/MCP startup', flush=True)
    # Every supported project kind can be the first TypeScript addition.
    for kind, options in [
        ('library', ['-D', 'First library']),
        ('worker', ['-t', 'redis', '-d', 'postgresql', '-D', 'First worker']),
        ('module', ['-m', 'cac-base', '-d', 'postgresql']),
    ]:
        app = root / (kind + '-first')
        initialize('First TypeScript project after native service')
        run('init', 'service', 'native-api', '--language', 'rust', '-D', 'Existing native service')
        native_source = (app / 'modules/native-api/lib.rs').read_bytes()
        run('init', kind, 'legacy-first', '--language', 'typescript', *options)
        manifest = tomllib.loads((app / '.forklaunch/manifest.toml').read_text())
        assert manifest['sdkTargets'] == ['typescript', 'rust']
        assert manifest['runtime'] == 'node'
        project_name = 'cac' if kind == 'module' else 'legacy-first'
        assert any(p['name'] == project_name for p in manifest['projects'])
        assert not (app / 'sdks').exists()
        assert (app / 'modules/native-api/lib.rs').read_bytes() == native_source
        assert (app / f'modules/{project_name}/package.json').is_file()
        run('init', 'service', 'second-native', '--language', 'rust', '-D', 'Native API after attachment')
        assert (app / 'Dockerfile.rust').is_file()
        print(f'PASS first TypeScript {kind} attachment and subsequent native initialization', flush=True)
    app = root / 'conflict'
    initialize('Reserved project collision')
    run('init', 'service', 'native-api', '--language', 'rust', '-D', 'Native API')
    before = snapshot()
    failed = run('init', 'library', 'core', '--language', 'rust', '-D', 'Conflicting core', success=False)
    assert 'already' in failed.stderr + failed.stdout
    assert snapshot() == before
    print('PASS reserved foundational project name rejects without changing either language', flush=True)
    assert not account_path.exists(), 'Local scaffolding unexpectedly created login credentials'
finally:
    if os.environ.get('FORKLAUNCH_KEEP_FIXTURE'):
        print(f'TypeScript attachment fixture evidence: {root}', flush=True)
    else:
        shutil.rmtree(root)
